/bin/zsh -lc "cat > tb.sv <<'EOF'
"'`timescale 1ns/1ps
module tb;
  reg clk_in = 0;
  reg rst = 0;
  wire clk_out7;

  TopModule dut(.rst(rst), .clk_in(clk_in), .clk_out7(clk_out7));

  always #5 clk_in = ~clk_in;

  integer i;
  initial begin
    $display("time clk rst cnt clkp clkn out");
    $monitor("%4t %b   %b   %0d   %b    %b    %b", $time, clk_in, rst, dut.cnt, dut.clkp, dut.clkn, clk_out7);
    #12 rst = 1;
    for (i = 0; i < 40; i = i + 1) begin
      @(posedge clk_in);
    end
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

